package com.lianxibu.site.config;
import com.lianxibu.site.domain.jobs.CollectorNodeFacts;import com.lianxibu.site.domain.protocol.*;import com.lianxibu.site.repository.jobs.*;import com.lianxibu.site.repository.settings.JdbcSettingsWrites;import com.lianxibu.site.service.jobs.*;import com.lianxibu.site.service.settings.SettingsJdbcStore;
import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.SmartLifecycle;import org.springframework.context.annotation.*;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
/** Host-owned node bindings and original native heartbeat facts; unknown remains unknown. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name={"site.ops.collector-monitoring.enabled","site.browser.enabled","site.collector.enabled"},havingValue="true")
public class CollectorNodeMonitoringConfiguration {
 public record Batch(List<CollectorNodeMonitoringCycle> cycles,CollectorNodeFacts.Api nativeFacts){public Batch{cycles=List.copyOf(cycles);if(cycles.isEmpty()||nativeFacts==null)throw new IllegalArgumentException("native collector monitors required");}@Override public String toString(){return "CollectorNodeMonitoringBatch[redacted]";}}
 @Bean Batch collectorNodeMonitoringBatch(DataSource source,PlatformTransactionManager tx,@Value("${SITE_COLLECTOR_MONITOR_NODES}")String location){return create(source,tx,load(location),Clock.systemUTC());}
 static List<String> load(String location){
  try{Path path=Path.of(location);if(!path.isAbsolute()||Files.isSymbolicLink(path)||!Files.isRegularFile(path)||Files.size(path)>65536)throw new IllegalArgumentException();byte[] raw=Files.readAllBytes(path);if(raw.length>65536)throw new IllegalArgumentException();var root=WireValues.object(CanonicalJson.parse(raw),Set.of("schema_version","node_ids"),Set.of("schema_version","node_ids"));if(!"collector-node-monitor-bindings-v1".equals(WireValues.text(root.get("schema_version"))))throw new IllegalArgumentException();var values=root.get("node_ids");if(!values.isArray()||values.isEmpty()||values.size()>128)throw new IllegalArgumentException();var nodes=new TreeSet<String>();for(var item:values)if(!nodes.add(WireValues.id(item,false)))throw new IllegalArgumentException();return List.copyOf(nodes);}catch(java.io.IOException|RuntimeException invalid){throw new IllegalStateException("collector operational bindings unavailable");}
 }
 public static Batch create(DataSource source,PlatformTransactionManager tx,List<String> nodes,Clock clock){
  Objects.requireNonNull(source);Objects.requireNonNull(tx);Objects.requireNonNull(clock);if(nodes==null||nodes.isEmpty()||nodes.size()>128)throw new IllegalArgumentException("collector operational bindings unavailable");var unique=new TreeSet<String>();for(String node:nodes)if(!unique.add(WireValues.id(node,false)))throw new IllegalArgumentException("collector operational bindings unavailable");
  var facts=new JdbcCollectorNodeFacts(source,tx,clock);var settings=new SettingsJdbcStore(new JdbcSettingsWrites(source),ignored->false,change->{throw new IllegalStateException("read-only collector monitoring settings");},clock);
  java.util.function.Supplier<OperationalMonitoringService.Configuration> current=()->{var config=settings.operationalConfiguration();return config.ready()?new OperationalMonitoringService.Configuration(config.revision(),config.rules()):null;};
  OperationalMonitoringService.ConfigurationSource configuration=()->{if(TransactionSynchronizationManager.isActualTransactionActive())return current.get();var reader=new TransactionTemplate(tx);reader.setReadOnly(true);reader.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);reader.setTimeout(10);return reader.execute(status->current.get());};
  var store=new OperationalJdbcStore(new JdbcOperationalSummaries(source),new JdbcJobRecords(source),clock);var monitor=new OperationalMonitoringService(store,configuration,new SharedWriteExecutor(new JdbcSharedWriteEntry(source),tx),clock);var cycles=new ArrayList<CollectorNodeMonitoringCycle>();for(String node:unique){var keys=List.of(new OperationalRuleEngine.Key("OPS-02","collector",node),new OperationalRuleEngine.Key("OPS-05","collector",node));cycles.add(new CollectorNodeMonitoringCycle(node,keys,facts,store,monitor,clock));}return new Batch(cycles,facts);
 }
 @Bean(destroyMethod="shutdownNow") @ConditionalOnMissingBean(name="collectorNodeMonitoringExecutor") ScheduledExecutorService collectorNodeMonitoringExecutor(){var executor=new ScheduledThreadPoolExecutor(1,task->{var thread=new Thread(task,"collector-node-monitor");thread.setDaemon(true);return thread;});executor.setRemoveOnCancelPolicy(true);executor.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);executor.setContinueExistingPeriodicTasksAfterShutdownPolicy(false);return executor;}
 @Bean Loop collectorNodeMonitoringLoop(Batch batch,@Qualifier("collectorNodeMonitoringExecutor")ScheduledExecutorService executor){return new Loop(batch,executor,Clock.systemUTC());}
 public static final class Loop implements SmartLifecycle {
  private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(Loop.class);private final Batch batch;private final ScheduledExecutorService executor;private final Clock clock;private boolean running,inFlight;private volatile boolean failure;private ScheduledFuture<?> future;private final List<Runnable> callbacks=new ArrayList<>();
  Loop(Batch batch,ScheduledExecutorService executor,Clock clock){this.batch=Objects.requireNonNull(batch);this.executor=Objects.requireNonNull(executor);this.clock=Objects.requireNonNull(clock);}
  @Override public synchronized void start(){if(running)return;if(inFlight)throw new IllegalStateException("collector sampling still stopping");batch.cycles().forEach(CollectorNodeMonitoringCycle::start);running=true;Instant now=clock.instant();long delay=Duration.between(now,now.truncatedTo(ChronoUnit.MINUTES).plusSeconds(60)).toNanos();try{future=Objects.requireNonNull(executor.scheduleAtFixedRate(this::tick,delay,TimeUnit.SECONDS.toNanos(60),TimeUnit.NANOSECONDS));}catch(RuntimeException rejected){running=false;batch.cycles().forEach(CollectorNodeMonitoringCycle::stop);future=null;throw rejected;}}
  private void tick(){synchronized(this){if(!running||inFlight)return;inFlight=true;}try{boolean failed=false;for(var cycle:batch.cycles()){synchronized(this){if(!running)break;}try{cycle.tick();}catch(RuntimeException unavailable){failed=true;}}if(failed&&!failure)LOG.warn("collector_node_monitoring_sample_failed");failure=failed;}finally{List<Runnable> done;synchronized(this){inFlight=false;done=List.copyOf(callbacks);callbacks.clear();}done.forEach(Runnable::run);}}
  @Override public void stop(){stop(null);}@Override public void stop(Runnable callback){boolean done;synchronized(this){running=false;batch.cycles().forEach(CollectorNodeMonitoringCycle::stop);if(future!=null){future.cancel(true);future=null;}done=!inFlight;if(!done&&callback!=null)callbacks.add(callback);}if(done&&callback!=null)callback.run();}
  @Override public synchronized boolean isRunning(){return running;}@Override public int getPhase(){return Integer.MAX_VALUE;}public boolean hasFailure(){return failure;}
 }
}
